export function adventureConfig(id){const factories={foundry:foundryConfig,harbor:harborConfig,seasoned:()=>trialConfig("seasoned"),veteran:()=>trialConfig("veteran"),tutorial:tutorialConfig,chapter:chapterConfig,classic:defaults,vigil:challengeConfig,archive:()=>archiveConfig(true),scarcity:()=>scarcityConfig(true),survival:()=>survivalConfig('formation'),hospice:()=>hospiceConfig('source')};if(!factories[id])throw Error('未知冒险');return factories[id]();}
export function chapterEnding(report){if(report.config.expedition==='foundry')return {title:report.won?'炉心归于沉寂，铸库重见海光。':'铸库仍在轰鸣，队伍暂退外港。',image:'foundry-v71.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/4 场；${report.party.filter(u=>u.hp>0).length} 人存活。余量：${report.supplies.herb}药草 / ${report.supplies.rune}符纸 / ${report.supplies.arrow}箭矢。装备与成长奖励请回营领取。`,won:report.won};if(!['chapter','harbor'].includes(report.config.expedition))return null;if(report.config.expedition==='harbor')return {title:report.won?'无光灯塔重新照亮盐风港。':'灯塔尚未点亮，远征队撤回海岸。',image:report.won?'harbor-seal-v41.png':'saltwind-harbor-v41.png',text:`通过 ${report.rooms.filter(r=>r.won).length}/4 场；${report.party.filter(u=>u.hp>0).length} 人存活。路线：${report.rooms.map(r=>r.name).join(' → ')}。`,won:report.won};const alive=report.party.filter(u=>u.hp>0).length,cleared=report.rooms.filter(r=>r.won).length;return {title:report.won?(alive===6?'沉钟归于寂静，六人归航。':'沉钟归于寂静，有人未能归航。'):'远征止步，灯火仍在等待。',image:report.won?'last-lantern-v17.png':'abbey.png',text:`肃清 ${cleared}/${roomsFor(report.config).length} 场；${alive} 人存活。药草 ${report.supplies.herb}、符纸 ${report.supplies.rune}、箭矢 ${report.supplies.arrow}。`,won:report.won};}
